export const HELP_FAQS: HelpFaq[] = [
  // ---------------------------------------------------------------- Getting started
  { topic: 'Getting started', q: 'What is WorkProvider360?', a: 'WorkProvider360 manages a home-care / field-service agency: clients and their payers, the team and their skills, scheduling and time tracking, visit approval, client invoicing and payroll, meetings, a client portal, reports, a live GPS map and AI analysis. Each agency has its own separate data and users.' },
  { topic: 'Getting started', q: 'How do I sign in?', a: 'Use the email and password your administrator gave you on the sign-in screen. If you forgot your password, click “Forgot password?” to receive a reset link by email, then set a new password from the link. Clients use the separate client sign-in page.' },
  { topic: 'Getting started', q: 'How do I find my way around?', a: 'The sidebar lists every page you have access to (it depends on your role and the permissions your Super Admin set). Collapse it to icons with the toggle in the top bar. The Overview page shows a summary of your agency or your own work, and the bell in the top bar shows your notifications.' },
  { topic: 'Getting started', q: 'I can’t reach the app / I’m offline', a: 'If you lose internet, the app shows a “No internet connection” screen and reconnects automatically once you are back online.' },

  // ---------------------------------------------------------------- Roles & access
  { topic: 'Roles & access', q: 'What are the roles?', a: 'Super Admin controls the whole workspace and all settings. Admin runs operations for their office and outranks Managers. Manager runs their team’s jobs and schedules Users. User (team member / caregiver) sees only their own work: accepting shifts, clocking in and out, notes and injury reports. Client is a portal-only role for the people the agency serves.' },
  { topic: 'Roles & access', q: 'Why can’t I see a page or a button?', a: 'Access is set per role. In Settings → Roles & Permissions and the Scheduling, Clients & Visits, Meetings, Messages, Log Access, Announcements and AI Analysis tabs, the Super Admin gives Admins and Managers None, Read or Write access. Read lets you view; Write lets you add and change. Admins and Managers also see only their own office’s data.' },
  { topic: 'Roles & access', q: 'Who can schedule whom?', a: 'You can only schedule people ranked below you: Super Admin schedules anyone, Admin schedules Managers and Users, and Managers schedule Users.' },

  // ---------------------------------------------------------------- Team
  { topic: 'Team', q: 'How do I add a team member?', a: 'Open Team and click “Add team member”. Enter the full name, email, a temporary password, role, phone and office. The member receives their login details by email. Admins can only add people to their own office.' },
  { topic: 'Team', q: 'How do I resend login details or unlock an account?', a: 'In Team, use “Resend” on a member’s row (it resets the password and emails new credentials), or select several members and use “Resend credentials” for all of them. A member locked out after too many failed sign-ins can be unlocked from their profile.' },
  { topic: 'Team', q: 'What is on a team member’s profile?', a: 'Open a member from Team to see their details, profile information (address, qualifications, experience, emergency contact, hire date), skills (the services they can provide), weekly availability and their schedule, where you can add shifts for them directly.' },
  { topic: 'Team', q: 'How do I filter or message the team?', a: 'Filter the Team list by office and role; it is paginated. Each row can send the member an SMS (when SMS is configured).' },

  // ---------------------------------------------------------------- Applications
  { topic: 'Applications', q: 'How do people apply to join?', a: 'Share the public Apply page. Applicants fill in their details, requested role, qualifications, experience, skills, availability, expected salary and any custom questions set in Settings → Application Form.' },
  { topic: 'Applications', q: 'How are applications approved?', a: 'Open Applications, review the applicant and click Approve or Reject. Approving creates the account and emails a temporary password; rejecting emails a notice with the reason. Applications can be exported to PDF.' },

  // ---------------------------------------------------------------- Offices
  { topic: 'Offices', q: 'How do offices work?', a: 'Offices group staff and clients (Offices page). Each office has an address, phone and timezone. Super Admins manage all offices; Admins and Managers work within their own office, and the people and clients they add are placed in it automatically.' },

  // ---------------------------------------------------------------- Clients
  { topic: 'Clients', q: 'How do I add a client?', a: 'Open Clients and click “Add client”. Fill in identity (name, gender, preferred language, date of birth), contact details, address, emergency contact, care and access information (access instructions, allergies, mobility and care notes), start date, office and the services they need. Required fields follow Settings → Clients & Visits. A default payer is created for every new client.' },
  { topic: 'Clients', q: 'How do I find and update clients?', a: 'Search and filter the Clients list by status (Active, On hold, Inactive) and service, then click View. On the client page you can edit details, change status and manage their schedule, care logs, payers and billing.' },
  { topic: 'Clients', q: 'What are the tabs on a client’s page?', a: 'Main (details and portal access), Schedule (calendar with “+ Add shift”), Care Logs (each visit’s clock-in/out, notes and signature), Payers (who pays and how) and Billing & Invoice (the client’s rates and invoices).' },
  { topic: 'Clients', q: 'Which caregivers can be assigned to a client?', a: 'When scheduling, the caregiver list shows each person’s office and skills. Settings → Clients & Visits can require the caregiver to be in the client’s office and/or to have the requested skill; caregivers who don’t match are labelled.' },

  // ---------------------------------------------------------------- Client portal
  { topic: 'Client portal', q: 'How do I give a client portal access?', a: 'Open the client’s Main tab and use the Portal access card: “Enable portal & email login” creates the login and emails it to the client and their active payers. “Resend credentials” emails a new temporary password, and “Disable” turns access off. The client needs an email address.' },
  { topic: 'Client portal', q: 'It says “The client portal is disabled for this agency”', a: 'A Super Admin must switch on “Client portal enabled” in Settings → Clients & Visits (and “Email credentials on enable” to send the login automatically). Then enable the client again.' },
  { topic: 'Client portal', q: 'What can clients see in the portal?', a: 'Their care summary, a calendar and list of visits with care logs, their services, their profile, and their invoices — the amount due, what is paid and a PDF download for each invoice.' },

  // ---------------------------------------------------------------- Skills & services
  { topic: 'Skills & services', q: 'What are skills & services?', a: 'Skills & Services lists the services your agency provides (for example nursing or companionship) with a category, description, colour and order. They are linked to clients (services they need), to team members (skills they have) and to shifts. Deactivate a service instead of deleting it. Who can edit them is set in Settings → Clients & Visits.' },

  // ---------------------------------------------------------------- Payers
  { topic: 'Payers', q: 'What is a payer and where do I manage payers?', a: 'A payer is whoever pays for a client’s care: insurance, Medicaid, Medicare, Veterans Affairs, a contract, a facility or a family member (private pay). Open Payers in the sidebar to search and filter by office, status and type, and click “+ Add payer” to create one as an Individual (first and last name) or a Company / facility (company name plus a contact person).' },
  { topic: 'Payers', q: 'What is on a payer’s page?', a: 'Details (type, contact details, address, notes and default bill / pay rates), Contacts (extra contact people) and Linked clients (every client the payer pays for). “Mark inactive” stops using a payer: it stays linked but is skipped for rates, new visits and invoices.' },
  { topic: 'Payers', q: 'How do I link a payer to a client?', a: 'Open the client’s Payers tab and click “+ Link payer”. Search the agency’s payers (or click “+ New payer”), then set the rank position, start and end dates, policy number, member ID, group, the subscriber (the client or someone else) and the payment distribution. One payer can be linked to many clients.' },
  { topic: 'Payers', q: 'What do rank and payment distribution mean?', a: 'Rank orders a client’s payers: 1 = Primary, 2 = Secondary… (use ▲ ▼ to reorder). Payment distribution says how each pays: Remainder (whatever is left), Split (a percentage), Per diem, Per visit, Weekly or Monthly (a fixed amount), or Authorization (only the hours its payer authorizations allow — see Payer authorizations). One payer pays the Remainder; Split payers together can cover at most 100%.' },
  { topic: 'Payers', q: 'Why can’t I deactivate a payer or change it from Remainder?', a: 'A client needs one payer for the remainder while it has any non-Authorization payer. Set another payer to Remainder first; the old one then becomes Split 0% and can be changed or deactivated. If all the client’s other payers are Authorization payers, the Remainder payer can be switched to Authorization or deactivated: the client then pays whatever the authorizations do not cover.' },
  { topic: 'Payers', q: 'What does “Sync to visits” do?', a: 'Each visit keeps its own copy of the client’s payers, taken when it is created. After changing payers, “Sync to visits” applies the current payers to the client’s visits that are not invoiced yet. Invoiced visits keep the payers they were billed with.' },

  // ---------------------------------------------------------------- Payer authorizations
  { topic: 'Payer authorizations', q: 'What is a payer authorization?', a: 'An authorization is a payer’s approval to pay for a number of service hours for one client and one service type over a period — for example “Medicaid authorizes John Smith for Personal Care from 01/01 to 12/31, up to 6 hours a day, 30 a week and 120 a month, Monday to Friday”. The authorized hours are billed to that payer; any extra hours go to the client’s next payer or to the client.' },
  { topic: 'Payer authorizations', q: 'Where do I manage authorizations?', a: 'Open Authorizations in the sidebar for every authorization of the agency, with Total / Active / Expiring soon counts, search and filters for payer, service type and status. A payer’s page has an Authorizations tab, and a client’s Payers tab shows that client’s authorizations. Click the eye icon to see how many hours are used and left, and which visits used them.' },
  { topic: 'Payer authorizations', q: 'How do I create an authorization?', a: 'First link the payer to the client with the payment distribution “Authorization” (client → Payers tab). Then click “+ Create Authorization”: choose the client, payer and service type, name it and add the payer’s authorization number, set the start and end dates, the maximum hours per day, week, month and/or in total (leave a limit empty when it does not apply), and tick the days on which services may be scheduled. The summary on the right updates as you type.' },
  { topic: 'Payer authorizations', q: 'How are a visit’s hours split between payers?', a: 'When a visit is saved its hours go through the client’s payers in rank order. Each Authorization payer takes the hours its authorization still allows that day, week, month and in total (the tightest limit wins). Whatever is left goes to the Remainder payer, or to the client as private pay when there is none. Example: an 8-hour visit with a 6-hours-a-day authorization bills 6 hours to that payer and 2 hours to the next payer or the client. Visits use the hours in date order, completed visits count their clocked hours, and cancelled or rejected visits use none.' },
  { topic: 'Payer authorizations', q: 'What happens when a visit exceeds an authorization?', a: 'The schedule form shows a Payer coverage panel with each payer’s hours and a warning (daily, weekly, monthly or total limit reached, day not allowed, no authorization for the service type, authorization expired). What happens on save is set in Settings → Scheduling: Allow (save without warning), Warn (save and show the warning — the default) or Block (the visit is rejected until it fits the authorization).' },
  { topic: 'Payer authorizations', q: 'What do the statuses mean?', a: 'Active — in use today. Upcoming — starts in the future. Expiring soon — ends within 30 days. Expired — the end date has passed. Inactive — switched off (it no longer covers visits; their hours move to the next payer or the client). Pending — the payer has not confirmed it yet. Hold — the payer has paused it. Pending and Hold still cover visits (scheduling goes on) but are shown in amber, need a note, and will not be billed. An Active authorization’s status (Upcoming, Expiring soon, Expired) is calculated from its dates; you choose Active, Pending, Hold or Inactive. Every change is kept in the status history (eye icon → History).' },
  { topic: 'Payer authorizations', q: 'Can an authorization count visits instead of hours?', a: 'Yes. Choose “Visits” as the limit unit: the day / week / month / total limits are then numbers of visits (whole numbers). Each visit uses one, whatever its length, and the payer covers the whole visit or none of it — once the count is used up, the visit goes to the next payer or the client.' },
  { topic: 'Payer authorizations', q: 'Will I be warned before an authorization ends?', a: 'Yes. The Super Admin and the Admins / Managers who manage authorizations for the client’s office get a notification and an email 30 days (configurable in Settings → Scheduling), 7 days and on the day before the end date. If you extend the end date, the reminders start again for the new date.' },
  { topic: 'Payer authorizations', q: 'What does the review step show when I edit an authorization?', a: 'Before saving changes to dates, days, limits, service type or status, the app shows which visits would get more hours from the authorization, which would lose hours (they move to the next payer or the client) and which are already invoiced and cannot change. Check it, then confirm.' },
  { topic: 'Payer authorizations', q: 'Why can’t I save or delete an authorization?', a: 'Two active authorizations for the same client, payer and service type cannot overlap in dates. The client and payer of an existing authorization cannot change (create a new one). Dates, weekdays or the service type cannot change in a way that leaves out visits that are already invoiced. An authorization that visits have used cannot be deleted — deactivate it instead.' },
  { topic: 'Payer authorizations', q: 'Who can manage authorizations?', a: 'A Super Admin always can. Admins and Managers get None, Read or Write access in Settings → Clients & Visits (by default Admins can manage and Managers can view), and they only see their own office’s clients.' },

  // ---------------------------------------------------------------- Scheduler
  { topic: 'Scheduler', q: 'How do I use the Scheduler?', a: 'The Scheduler shows shifts by day, week or month, coloured by team member; filter by member and move between dates. Click an empty slot (or “Add job”) to create a shift, or click a shift to see its details, notes, time entries and care log.' },
  { topic: 'Scheduler', q: 'How do I create a shift?', a: 'Choose the client (their address and service fill in), service type, caregiver, title, date and times, status (Scheduled, Approved or Cancelled), bill and pay rate per hour and overtime multiplier. Optionally email Admins / Managers. The caregiver is notified by email (and SMS when configured). When the client has Authorization payers, a Payer coverage panel shows how the visit’s hours split between the payers and the client before you save.' },
  { topic: 'Scheduler', q: 'What is a scheduling conflict?', a: 'Before saving, the app checks whether the caregiver already has a shift at that time and shows a “Scheduling conflict” box. Click “Ignore & save” to save anyway, or Cancel to change the time.' },
  { topic: 'Scheduler', q: 'How do team members respond to shifts?', a: 'The assigned member opens the shift and clicks Accept or Reject (with a reason). They can add notes and report an injury, which is emailed to admins and managers.' },
  { topic: 'Scheduler', q: 'Can I edit or delete a shift?', a: 'Yes, with Write access to scheduling: open the shift and use “Edit schedule” or Delete. A visit that is on a client invoice cannot be deleted — cancel it instead. Editing a visit that came from a master schedule marks it “edited”, so later changes to the master schedule leave it alone.' },
  { topic: 'Scheduler', q: 'What are compatibility warnings?', a: 'When you pick a caregiver the app checks the client’s compatibility settings: caregivers on the client’s do-not-send list, missing a required attribute (e.g. “Speaks Spanish”), having an attribute the client wants to avoid, or not matching the preferred caregiver gender. Depending on Settings → Scheduling they are allowed, shown as a warning you can ignore, or blocked.' },
  { topic: 'Scheduler', q: 'How do I confirm shifts?', a: 'The caregiver confirms a shift by tapping Accept. Shifts that are assigned but not accepted yet are listed under “Pending confirmation”, where you can send a reminder. If Settings → Scheduling has a reminder time (24 hours by default), caregivers get one automatic reminder that many hours before the shift.' },

  // ---------------------------------------------------------------- Master schedules
  { topic: 'Master schedules', q: 'What is a master schedule?', a: 'A master (recurring) schedule describes a client’s regular care once — for example Personal Care every Monday and Wednesday 9:00–13:00 with Maria and Friday 14:00–17:00 with Ahmed — instead of creating every visit by hand. It repeats weekly, every other week, or monthly (on a date such as the 15th, or a weekday such as the 2nd Tuesday or the last Friday), from a start date to an optional end date.' },
  { topic: 'Master schedules', q: 'How do I create one?', a: 'Open Master schedules → “+ New master schedule”, or choose “Repeat” when adding a shift in the Scheduler. Pick the client, service type, title and default caregiver (or none for open shifts), the pattern, the dates and the time slots (day, start, end and an optional different caregiver per slot). Rates can be left empty to use the usual rate rules. “Auto-publish” keeps visits published that many weeks ahead.' },
  { topic: 'Master schedules', q: 'What does publishing do?', a: 'Publishing turns the pattern into real visits for a date range (up to 8 weeks). The preview shows each visit as new, already published, warning or conflict. Visits whose caregiver is busy, not available, blocked by the client or over the authorization (with the Block setting) are skipped with the reason — or created as open shifts if you tick “publish as open shift”. Publishing the same range again never creates duplicates.' },
  { topic: 'Master schedules', q: 'What happens when I change a master schedule?', a: 'Visits that are not published yet always follow the new pattern. Already published visits change only if you tick “Apply to published visits from …”: those that have not started, are not invoiced and were not edited by hand get the new times and caregiver; visits for removed slots are deleted (or cancelled if time was recorded). Pause stops auto-publishing; End sets the last day and can remove the unstarted visits after it.' },

  // ---------------------------------------------------------------- Open shifts
  { topic: 'Open shifts', q: 'What is an open shift?', a: 'A visit without a caregiver. Create one by switching on “Open shift” in the shift form, or let a master schedule publish open shifts. The app offers it to the eligible caregivers (right skills and office, free at that time, not blocked by the client) by notification, push and email.' },
  { topic: 'Open shifts', q: 'How do caregivers take an open shift?', a: 'Caregivers see “Available shifts” on the Open shifts page and tap Interested or Decline. By default the office then chooses: the Open shifts page lists each shift with the interested caregivers and their match score, and “Assign” gives it to one of them (the others are told it was filled). With the “first to accept” setting, the first caregiver who taps Interested gets the shift straight away.' },
  { topic: 'Open shifts', q: 'What is “Fill open shifts”?', a: 'It proposes the best available caregiver for every open shift in a date range, in start order, without double-booking anyone. Review the proposals, untick any you do not want, and click Apply to assign them.' },

  // ---------------------------------------------------------------- Compatibility & suggestions
  { topic: 'Compatibility & suggestions', q: 'How do I record what a client needs?', a: 'Settings → Care attributes holds the agency’s list (for example “Speaks Spanish”, “Comfortable with cats”, “Non-smoker”, “Hoyer lift trained”). On the client’s Compatibility tab mark attributes as Required, Preferred or Avoid, choose a preferred caregiver gender, and add Preferred or Blocked caregivers (Blocked = do-not-send). On a team member’s profile tick the attributes they have and set their home location.' },
  { topic: 'Compatibility & suggestions', q: 'How does “Suggest caregiver” rank people?', a: 'Each caregiver gets a score out of 100: skill for the service (20), availability at that time (20), compatibility with the client’s needs (20), continuity — preferred by the client or recent visits together (15), distance from the client (15, needs locations) and workload this week (10, lower near overtime). Caregivers who are busy, blocked, in another office or missing the skill (when those rules are on) are listed separately with the reason.' },

  // ---------------------------------------------------------------- Missed clock-ins
  { topic: 'Missed clock-ins', q: 'How are missed clock-ins detected?', a: 'Every few minutes the app checks visits in each office’s local time. If a caregiver has not clocked in 15 minutes after the start (or out 15 minutes after the end — both configurable in Settings → Scheduling), the visit is listed under Missed clock-ins and the caregiver and the office get a notification once. Visits the auto clock-in/out settings fill are skipped. A late clock-in resolves it automatically and records how late it was.' },
  { topic: 'Missed clock-ins', q: 'How do I resolve one?', a: 'Open Missed clock-ins and choose “Add time” (enter the real clock-in / clock-out and a reason), “No-show” (cancels the visit) or “Dismiss”. Resolved items stay in the list with who resolved them and how.' },

  // ---------------------------------------------------------------- Calendar feed
  { topic: 'Calendar feed', q: 'Can I see my visits in Google, Apple or Outlook calendar?', a: 'Yes. In My Profile → Calendar feed click “Create link” and copy it. In Google Calendar use Other calendars → + → From URL; in Apple Calendar File → New Calendar Subscription; in Outlook Add calendar → Subscribe from web. Your visits from two weeks ago to three months ahead appear at the agency’s local time. Calendar apps refresh subscribed calendars on their own schedule (Google can take several hours).' },
  { topic: 'Calendar feed', q: 'Is the calendar link private?', a: 'The link contains a secret code: anyone who has it can see your visits, so do not share it. “Regenerate” makes a new link and stops the old one; “Turn off” disables it.' },

  // ---------------------------------------------------------------- Time tracking & visits
  { topic: 'Time tracking & visits', q: 'How do I clock in and out?', a: 'Open your shift and click Clock in, then Clock out when done. Depending on Settings → Clients & Visits, your GPS location is recorded and the client may need to sign on clock-in and / or clock-out. After one full clock-in/out the buttons lock for that shift.' },
  { topic: 'Time tracking & visits', q: 'What is auto clock-in/out?', a: 'If enabled (Settings → Scheduling, and per-visit options in Clients & Visits), the system records the scheduled hours for a shift nobody clocked in/out on once it has ended. It never interrupts a shift in progress.' },
  { topic: 'Time tracking & visits', q: 'How do I add or fix time manually?', a: 'Managers with Write access can add or edit a time entry on a shift with a note, for example when someone forgot to clock out.' },
  { topic: 'Time tracking & visits', q: 'What is a care log?', a: 'Each visit’s care log shows clock-in and clock-out times and locations, notes, injury reports and the client’s signature. Open it from the shift on the Scheduler or from the client’s Care Logs tab.' },

  // ---------------------------------------------------------------- Approvals
  { topic: 'Approvals', q: 'How do I approve a schedule?', a: 'Choose Status “Approved” when creating the shift, or open it on the Scheduler and click “Approve” (and “Remove approval” to undo). Approved shifts show a ✓ on the calendar. Cancelled or rejected shifts cannot be approved.' },
  { topic: 'Approvals', q: 'Who can approve, and why does approval matter?', a: 'Only approved visits are invoiced by default. A Super Admin can always approve; in Settings → Scheduling → Schedule approval & invoicing the Super Admin decides whether Admins and Managers can approve, and which roles may invoice unapproved visits.' },

  // ---------------------------------------------------------------- Billing & invoices
  { topic: 'Billing & invoices', q: 'How are a shift’s bill and pay rates chosen?', a: 'Each rate fills in separately from the first place that has one: the client’s own rates (Billing & Invoice tab), then the client’s payers in rank order that are active on the visit date, then the agency defaults in Settings → Scheduling. The form shows where each rate came from.' },
  { topic: 'Billing & invoices', q: 'What is a rate conflict?', a: 'If no bill or pay rate is found anywhere, the shift form shows a “Rate conflict”. Set the missing rate, or click “Ignore & save” to create the shift anyway (it bills or pays 0 until a rate is added).' },
  { topic: 'Billing & invoices', q: 'How do I invoice clients and payers?', a: 'Open Billing → Invoice runs → “New run”: choose the service period and optional filters (office, client, payer type, payer or client bills, include unapproved visits). The preview groups every billable visit share by who pays it — each payer is billed only its share (for example the hours its authorization covers) and the client the rest. Create the run to get Draft invoices, review them (remove lines or invoices you do not want), then Finalize: each invoice gets its number (e.g. INV-2026-000123), invoice date and due date. A single client can be invoiced the same way from their Billing tab.' },
  { topic: 'Billing & invoices', q: 'Why are some visits left out of an invoice?', a: 'Only approved visits are invoiced by default — a popup explains it and offers “Approved only”, or “Invoice all” when your role may invoice unapproved visits. Visit shares already on another invoice (that is not void), cancelled or rejected visits are never billed again.' },
  { topic: 'Billing & invoices', q: 'What are billing codes, units and rounding?', a: 'In Settings → Billing → Billing codes you set, per service type (and optionally per payer), the procedure code (for example T1019), up to four modifiers, revenue code, place of service, the unit (hour, 15 minutes, 30 minutes, visit or day), the rounding rule (none, nearest — the 8-minute rule for 15-minute units — up or down), minimum units and an optional rate per unit. Without a rate per unit the hourly bill rate is converted (e.g. $28/h → $7 per 15-minute unit). Services without a code are billed in hours as before. Authorization modifiers override the code’s modifiers.' },
  { topic: 'Billing & invoices', q: 'What do the invoice statuses mean?', a: 'Draft — created by a run, not numbered yet, can still be changed or deleted. Issued — finalized and owed. Partially paid — some of it is paid. Paid — nothing left to pay. Void — cancelled; its visits can be billed again. Paid and Partially paid follow the payments and adjustments you record — you never set them by hand.' },
  { topic: 'Billing & invoices', q: 'How do I correct an invoice?', a: 'Small corrections use adjustments (write-off, discount, credit, debit) on the invoice or one line. To redo an invoice, Void it (only possible while no payment is applied — reverse the payment first) with a reason; its visits become billable again and a new run creates the replacement invoice.' },
  { topic: 'Billing & invoices', q: 'How do I send or download an invoice or statement?', a: 'Use PDF to download an invoice, or Send to email it to the bill-to email (with a “Pay online” link when online payments are on). Statements list a client’s or payer’s open invoices, recent payments and aging — download or email them from Billing → Statements or the client’s Billing tab. Clients see their invoices and balances in the portal.' },

  // ---------------------------------------------------------------- Payments & receivables
  { topic: 'Payments & receivables', q: 'How do I record a payment?', a: 'Billing → Payments → “Record payment”: choose who paid (a payer or the client), the method (check, EFT/ACH, card, cash, other), reference number, date and amount. The app proposes how to apply it to that party’s open invoices, oldest first — change the amounts if needed. Anything not applied stays as an unapplied credit you can apply later or refund. One payer check can be applied to invoices of many clients.' },
  { topic: 'Payments & receivables', q: 'What are adjustments and write-offs?', a: 'Adjustments change what is owed without money: write-off (bad debt), contractual (the payer’s allowed amount is lower), discount, credit, debit, patient responsibility or other, with a note and optional reason code. Write-offs above the limit in Settings → Billing (default $500) need a Super Admin.' },
  { topic: 'Payments & receivables', q: 'How do I undo a payment or give money back?', a: 'Nothing is deleted. “Reverse” a payment (bounced check, posted to the wrong client — Super Admin) to remove its applications and restore the balances. “Refund” returns money from an overpayment or unapplied credit and records the method, reference and date.' },
  { topic: 'Payments & receivables', q: 'What does the aging report show?', a: 'Billing → Aging groups unpaid balances by days past the due date: current, 1–30, 31–60, 61–90 and over 90 days, by payer, by client or by payer vs. private pay, with drill-down to the invoices. The payments report lists money received by date and method.' },

  // ---------------------------------------------------------------- Claims & remittance
  { topic: 'Claims & remittance', q: 'How do electronic claims work?', a: 'For payers set to “837P claim” (payer profile → EDI), finalizing an invoice creates a claim with the procedure codes, units, modifiers, authorization number and the client’s diagnoses. On Billing → Claims run “Validate” — missing items (agency NPI / tax ID / taxonomy, member ID, payer EDI ID, diagnoses, authorization number…) are listed per claim — then “Generate batch” to create the 837P file: download it and upload it to your clearinghouse, or let the app send it by SFTP when configured in Settings → Billing → Clearinghouse.' },
  { topic: 'Claims & remittance', q: 'How do I know if a claim was accepted?', a: 'The clearinghouse returns a 999 (file accepted or rejected) and a 277CA (each claim accepted or rejected). They are read automatically from SFTP, or upload them on Billing → Remittances. Each claim shows its status and a timeline; rejected claims appear in the work queue with the reason.' },
  { topic: 'Claims & remittance', q: 'How do I fix a rejected or wrong claim?', a: 'Correct the data (for example the member ID or code), then “Resubmit as replacement” — the app sends a replacement claim (frequency 7) with the payer’s claim number. “Void claim” sends a cancellation (frequency 8).' },
  { topic: 'Claims & remittance', q: 'How are remittances (835 / ERA) posted?', a: 'ERA files are read from SFTP or uploaded on Billing → Remittances. Each claim and line is matched by its claim number and line control number only — anything that does not match goes to the unmatched queue for you to match by hand. Posting creates one payment for the ERA, applies the paid amounts to the invoice lines and records the adjustments: contractual (CO), patient responsibility (PR — moved to the client’s next invoice) and other (OA/PI), with the reason codes. Claims become Paid, Partially paid or Denied.' },

  // ---------------------------------------------------------------- Eligibility
  { topic: 'Eligibility', q: 'How do I check insurance or Medicaid eligibility?', a: 'Use “Check eligibility” on a client’s payer (or Billing → Eligibility for one client or a bulk check of all clients with insurance / Medicaid payers). The result shows active or inactive coverage, plan, group and coverage dates and is kept in the history. A result from the last 30 days is reused unless you force a new check; bulk checks are capped per run. Without an eligibility service you can record a result you checked on the payer’s portal (“Manual”).' },

  // ---------------------------------------------------------------- Online payments & QuickBooks
  { topic: 'Online payments & QuickBooks', q: 'Can clients pay invoices online?', a: 'Yes. A Super Admin connects the agency’s own Stripe account in Settings → Billing → Online payments (the money goes to the agency’s account). Then invoices in the client portal and invoice emails show “Pay online”; the client pays by card on a secure Stripe page and the payment is recorded and applied automatically.' },
  { topic: 'Online payments & QuickBooks', q: 'How does QuickBooks Online sync work?', a: 'Connect QuickBooks Online in Settings → Billing → QuickBooks and map each service type to a QuickBooks item. From then on clients and payers (as customers), finalized invoices, payments, adjustments (credit memos) and voids are sent to QuickBooks automatically within a few minutes. Anything that fails is listed there with Retry and Mark resolved. The sync is one way — changes made in QuickBooks are not brought back.' },

  // ---------------------------------------------------------------- Accounting & payroll
  { topic: 'Accounting & payroll', q: 'What can I do in Accounting?', a: 'Super Admins pay Admins and Managers their salary (Salaries), pay Users their shift pay for a date range (Shift Pay), invoice clients (Client Invoices) and review everything paid (Paid Invoices). Every payment creates a PDF invoice stamped PAID that is emailed to the recipient.' },
  { topic: 'Accounting & payroll', q: 'How do online payments work?', a: '“Pay online” uses Stripe checkout; when payment completes you return to Accounting and the payment is recorded and emailed. “Cash” records it immediately.' },
  { topic: 'Accounting & payroll', q: 'Why does Shift Pay show “not approved”?', a: 'Shift Pay shows how many of each worker’s shifts are approved. Paying with unapproved shifts opens a popup: pay approved shifts only, or everything when your role may pay for unapproved shifts.' },

  // ---------------------------------------------------------------- Point of sale
  { topic: 'Point of sale', q: 'What is Point of Sale?', a: 'A sandbox for charging a customer’s card (Super Admin and Admin). It shows transactions and an earnings summary; the platform earns a percentage-plus-fixed fee on approved sales (set in its fee settings). No real money is charged.' },

  // ---------------------------------------------------------------- Meetings
  { topic: 'Meetings', q: 'How do I create a meeting?', a: 'Open Meetings and click “+ New Meeting”. Enter title, description, start and end, location or link, type (In person, Online, Hybrid), maximum participants, colour and notes. Tick “Paid meeting” and set a fee per participant when paid meetings are allowed.' },
  { topic: 'Meetings', q: 'How do participants and RSVPs work?', a: 'Open a meeting and use “Add Participant” to invite team members (and clients when allowed). Invitees get an email and answer Accept, Decline or Maybe; the organiser sees everyone’s status.' },
  { topic: 'Meetings', q: 'How do I record meeting payments?', a: 'For paid meetings use “Record Payment” (amount, method, transaction ID, notes). The Meeting Payments panel shows unpaid vs collected totals and the payment history.' },

  // ---------------------------------------------------------------- Custom messages
  { topic: 'Custom messages', q: 'How do I send a custom message?', a: 'Click the envelope (“Send message”) in the top bar, just left of Settings, or open Communication → Messages and click “New message”. Add recipients in To (and optionally CC and BCC), choose a Reply-To, enter the Subject and write the Message in the editor, attach files if needed, then click Send Message. A confirmation shows how many emails will go out; after you confirm, the message is queued and you are taken to its delivery page. The envelope only appears when your role is allowed to send.' },
  { topic: 'Custom messages', q: 'Who can I send to, and how do groups work?', a: 'Start typing in To, CC or BCC to pick team members, clients (with an email address) or groups such as “All active staff”, a role (Admins, Managers, Team members…), an office, “All active clients” or the clients of one office. Groups are expanded when the message is sent, so they always contain the current active members with an email. You can also type a full email address and press Enter or comma — unless your Super Admin turned external addresses off. Admins, Managers and Users can only reach people of their own office; Users cannot email clients.' },
  { topic: 'Custom messages', q: 'What is the Recipients Summary?', a: 'The panel next to the form counts the real recipients as you add chips: To, CC and BCC, a copy to you, and the total number of emails. It lists anyone who will be skipped (inactive, no email address, outside your office, invalid or external not allowed) and how many duplicates were removed. If the same address is in several fields, To wins over CC and CC over BCC. A message cannot exceed the maximum recipients set in Settings → Messages.' },
  { topic: 'Custom messages', q: 'How are To, CC and BCC delivered?', a: 'Every To recipient gets their own email, so nobody sees the other To addresses — even with a group of hundreds. CC recipients get one shared copy, marked as a copy of a message sent to N recipients. BCC recipients get one hidden copy. “Send a copy to me” sends one extra copy to you. Insert {{FirstName}} or {{FullName}} from the editor toolbar to personalise the text; each To recipient sees their own name (CC and BCC copies show the first recipient’s).' },
  { topic: 'Custom messages', q: 'What do the Reply-To choices mean?', a: 'No reply uses the system no-reply address. My email sends replies to your own address. Agency email sends them to the agency notification email. Custom address lets you type any reply-to address (only when external addresses are allowed). Your Super Admin chooses which of these are offered. The email always comes from the system address with the name “{Agency} via WorkProvider360”.' },
  { topic: 'Custom messages', q: 'What can I attach and what are the limits?', a: 'Click Attach File (or drop files on it). Up to 5 files, each at most 10 MB, of type PDF, DOC, DOCX, XLSX, JPG or PNG; the whole message, including images placed in the text, can be at most 20 MB. Images inserted in the editor (PNG or JPEG) are sent inside the email. Attachments are kept for the number of days set in Settings → Messages, then deleted — the message and its recipient list stay.' },
  { topic: 'Custom messages', q: 'What does the editor support?', a: 'Paragraph and heading styles, bold, italic, underline, strikethrough, alignment, numbered and bulleted lists, links, images and tables (click inside a table to add rows or columns or delete it). The <> button switches to the HTML source and the expand button opens the editor full screen (Esc to leave). The character count is shown at the bottom right. Scripts and unsafe formatting are removed by the server before sending.' },
  { topic: 'Custom messages', q: 'How do I preview a message?', a: 'Click Preview. The server builds the email exactly as recipients will see it — agency banner, your text after the safety clean-up, personalisation filled in with the first To recipient, the From name and the Reply-To address. You can send straight from the preview.' },
  { topic: 'Custom messages', q: 'Where do I see sent messages, and how do I retry failures?', a: 'Communication → Messages lists messages with date, subject, sender, recipients, sent and failed counts and status (Queued, Sending, Sent, Partially failed, Failed or Deferred). Filter by status, dates or text, or tick “Mine only”. Open a message to see its body, download attachments and check each recipient’s status and error; the page refreshes itself while sending. “Retry failed” queues only the failed recipients again, and “Duplicate” opens the composer with the same subject and text. Messages are sent in the background at a steady rate; when the agency’s daily limit is reached the rest is Deferred to the next day. A red dot on the envelope means one of your recent messages has failed recipients.' },
  { topic: 'Custom messages', q: 'Who can send messages and where is it configured?', a: 'Super Admins can always send and see every message and edit Settings → Messages. There they set Admin and Manager access (None, Read = see sent messages, Write = send and see), whether Users may send to their own office’s staff, whether typed external addresses are allowed, which Reply-To choices are offered, the maximum recipients per message, the daily sending limit, the send rate per second and how many days attachments are kept. Admins and Managers see their office’s messages (or only their own with “Mine only”); Users see only their own.' },
  { topic: 'Custom messages', q: 'How do I send a push notification?', a: 'Open the Send Custom Message page (the envelope in the top bar, or Communication → Messages → “New message”) and switch the toggle at the top from Email to “Push notification” (the arrow keys switch it too). Add people or groups in To, enter a Title (up to 100 characters — phones show about the first 65) and a plain-text Message (up to 500 characters), and use the {{FirstName}} / {{FullName}} buttons to personalise it. Tick “Send to my devices too” to get it yourself. Preview shows how it will look on an Android phone; Send asks “Send push to N people?”, then queues it and opens its delivery page. Your recipients and text are kept when you switch between Email and Push. If the Push option is greyed out, the reason is shown next to it (for example push is turned off for the agency, or not set up on the server yet).' },
  { topic: 'Custom messages', q: 'Who receives a push, and what does “In app only” mean?', a: 'Pushes go to team members and to clients who have an app login — a client without one is skipped (“no app account”). Typed email addresses, CC and BCC are not used for push. Everyone receives the message in their notification bell (on the web and in the app). People signed in to the WorkProvider360 app on a phone also get a push on that phone; people without a registered phone are counted as “In app only” — they still see it in the bell. The Recipients Summary shows the number of people, how many have the app on a phone, how many are in app only, and anyone skipped with the reason.' },
  { topic: 'Custom messages', q: 'What are the limits of a push?', a: 'Title 1–100 characters and message 1–500 characters, plain text only — no links, images, formatting or attachments. The same maximum recipients per message as email applies (Settings → Messages), but there is no daily limit for pushes. Pushes are sent in the background at the push send rate set in Settings → Messages. Scheduled pushes, images and links to a specific app screen are not available yet.' },
  { topic: 'Custom messages', q: 'Which phones get pushes?', a: 'Only the WorkProvider360 Android app receives pushes; there is no iPhone app yet, so iPhone users see the message in the bell on the web. A person must be signed in to the app and have allowed notifications. Tapping the push opens the app (with the latest app version it opens that notification).' },
  { topic: 'Custom messages', q: 'What should I not put in a push?', a: 'Pushes appear on the phone’s lock screen, where anyone nearby can read them. Don’t include client health details or other private information — keep it short and ask people to open the app or contact the office for details.' },
  { topic: 'Custom messages', q: 'How do I check push delivery?', a: 'Communication → Messages has a Channel column (envelope = email, bell = push) and a Channel filter. Open a push to see its title and message and the counts Sent (reached at least one phone), In app only (bell only) and Failed. Each recipient shows their status and how many of their devices received or rejected the push. “Retry failed” sends again to the failed people only, and “Duplicate” opens the composer on Push with the same title and message.' },
  { topic: 'Custom messages', q: 'How is push configured?', a: 'In Settings → Messages a Super Admin can turn “Allow push notifications” on or off and set the push send rate (1–100 per second). Push uses the same role access as email: a role with Write can send both. Push also needs the push switch and the “Custom push notifications” event to be on in Settings → SMS & Push, and Firebase to be set up on the server.' },

  // ---------------------------------------------------------------- Announcements & notifications
  { topic: 'Announcements & notifications', q: 'How do announcements work?', a: 'Super Admins post announcements on the Announcements page. Which roles can see them is set in Settings → Announcements.' },
  { topic: 'Announcements & notifications', q: 'What notifications will I get?', a: 'The bell shows in-app notifications. Emails are sent when you are scheduled, for injury reports, meeting invites, credentials, invoices and payments; SMS is sent for schedules when it is configured.' },
  { topic: 'Announcements & notifications', q: 'How do I mark notifications as read?', a: 'Click the bell in the top bar to see your notifications; unread ones are highlighted with a dot and the badge shows how many. Click a notification to mark it read (long text expands); “Mark all read” clears them all. Custom push messages show who sent them (“From …”).' },

  // ---------------------------------------------------------------- Reports & live map
  { topic: 'Reports & live map', q: 'What do Reports show?', a: 'Reports summarise hours worked (regular and overtime) and pay per person for a date range, with totals.' },
  { topic: 'Reports & live map', q: 'How does the Live Map work?', a: 'Super Admins, Admins and Managers see team members’ live GPS location while they are clocked in, updated in real time, and can view a shift’s location trail.' },

  // ---------------------------------------------------------------- Training portal
  { topic: 'Training portal', q: 'What is the Training portal and how do I open it?', a: 'The Training portal is a separate area for staff training with its own sign-in. If it is enabled for you, a “Training” tab appears in the sidebar and opens the portal without signing in again. You can also sign in directly on the training sign-in page (/training-login) with the training username and password that were emailed to you. Signing out of the training portal does not sign you out of the main app.' },
  { topic: 'Training portal', q: 'Who can enable the training portal for someone?', a: 'Super Admins can enable it for anyone, Admins for Managers and Users (caregivers), and Managers for Users. Use the “Enable training portal” switch when adding a team member, the Training portal card on a member’s profile, or the Access tab inside the training portal. Enabling creates a training username and emails a password to the person.' },
  { topic: 'Training portal', q: 'Can I see someone’s training password?', a: 'No. Passwords are stored securely and cannot be read back. Super Admins can see training usernames on the Access tab, and when they click “Reset password” the new password is shown once (and emailed). Admins and Managers can reset passwords too; the new password is emailed to the person. After 5 wrong training passwords, sign-in is blocked until the password is reset.' },
  { topic: 'Training portal', q: 'What kinds of trainings are there?', a: 'Videos, PDF documents and quizzes. Super Admins and Admins create them in the Catalog: upload a video or PDF (stored in your agency’s Cloudinary account) or paste a link, or build a quiz with answers and a pass mark. Managers can view the catalog to choose what to assign. Archived trainings can no longer be assigned.' },
  { topic: 'Training portal', q: 'Who can assign trainings?', a: 'Super Admins assign to Admins (and anyone below), Admins assign to Managers and Users, and Managers assign to Users. Go to Team Trainings → “Assign training”, pick the training, the people, a due date and an optional note. Only people with the training portal enabled can be assigned, and a person can’t have the same training open twice.' },
  { topic: 'Training portal', q: 'How do I complete a training?', a: 'Open it from My Trainings. Watch the video to the end, read the PDF, or answer the quiz and submit — if you don’t reach the pass mark you can try again. Your progress is saved as you go. When finished it moves to “Awaiting approval”. If a reviewer sends it back you’ll see their reason and can redo it.' },
  { topic: 'Training portal', q: 'Who approves completed trainings?', a: 'Admins approve Managers’ and Users’ trainings, Managers approve Users’ trainings, and Super Admins can approve everyone’s. Open Approvals in the training portal to Approve, Send back (a reason is required) or Cancel. Nobody can approve their own training.' },
  { topic: 'Training portal', q: 'Where can I see training status and reports?', a: 'The training Dashboard shows your progress and, for leaders, the team’s open, overdue and awaiting-approval counts. Every status change (assigned, started, submitted, approved, sent back, cancelled) is recorded in each training’s History and in Reports, where you can filter by dates and status and export a CSV. Training also appears in AI Analysis as “Training Compliance”.' },
  { topic: 'Training portal', q: 'What emails does the training portal send?', a: 'Emails go out when a training is assigned, completed and waiting for approval, approved, sent back or cancelled. Every morning (06:00 UTC) people get a “today is the last date” reminder for trainings due that day, and a “not completed” notice goes to the trainee and the person who assigned it when a due date passes. The Super Admin can turn these reminders on or off and set the default due days in Training → Settings.' },

  // ---------------------------------------------------------------- AI Analysis & assistant
  { topic: 'AI Analysis & assistant', q: 'What is AI Analysis?', a: 'Neural networks trained on your agency’s own history predict how the agency is doing: an overall health score, and for each area KPIs, charts with forecasts, findings, recommended actions and risk tables. Areas: Workforce Reliability, Shift Demand, Client Retention, Revenue & Payroll, Meetings, Recruitment, Security, Product Adoption, Office Performance, Billing & Approvals and Payer Mix & Coverage.' },
  { topic: 'AI Analysis & assistant', q: 'How do I run, save and share an analysis?', a: 'Open AI Analysis → New analysis, tick the areas, choose how much history to train on and how far ahead to predict, then “Run analysis”. Every report is saved under History; download it as PDF or HTML or email it to Admins and Managers. A daily report can be emailed automatically (Settings → AI Analysis).' },
  { topic: 'AI Analysis & assistant', q: 'What is the chat assistant?', a: 'The assistant button (bottom corner, draggable) answers questions about how to use WorkProvider360. It remembers your conversation; clear it from the chat window. It explains features but does not read your agency’s data.' },

  // ---------------------------------------------------------------- Security & logs
  { topic: 'Security & logs', q: 'What does the Security page show?', a: 'Super Admins see sign-in analytics (successful and failed logins, unauthorised access), detected threats such as SQL-injection attempts and request spikes, and the client IP of each event. Export it to PDF.' },
  { topic: 'Security & logs', q: 'What are Email Logs?', a: 'Every email the system sent, with its status. Super Admins always see them; Admins and Managers only when allowed in Settings → Log Access.' },
  { topic: 'Security & logs', q: 'Are changes to data recorded?', a: 'Yes. Every change to agency data (clients, payers, schedules, invoices, settings and more) is recorded with who made it and when, so changes can be traced. Passwords and large files are never copied into that record.' },

  // ---------------------------------------------------------------- Settings
  { topic: 'Settings', q: 'What can I change in Settings?', a: 'Company Profile, Team Members, Roles & Permissions, Scheduling (defaults, approval & invoicing), Meetings, Messages, Clients & Visits, Application Form, Log Access, Announcements, AI Analysis and Login Page. Most tabs are Super Admin only; others are read-only for your role.' },
  { topic: 'Settings', q: 'What is in Settings → Scheduling?', a: 'Admin / Manager scheduling access, default bill rate, pay rate and overtime multiplier for new shifts, admin / manager notifications on new shifts, auto clock-in/out, Schedule approval & invoicing (who can approve, who can invoice unapproved visits), and what happens when a visit exceeds a payer authorization (Allow, Warn or Block — Super Admin only). The “Scheduling automation” card (Super Admin) sets the missed clock-in / clock-out grace minutes and who is notified, how open shifts are given out (office picks or first to accept), the confirmation reminder time, the compatibility rule (Allow, Warn or Block) and how many days before the end date authorization reminders start.' },
  { topic: 'Settings', q: 'What is in Settings → Clients & Visits?', a: 'Client, service-type and payer-authorization access for Admins and Managers; visit rules (auto clock-in/out, client signature on clock-in/out, GPS capture, same office, matching skill); the client portal switch and credentials email; client notifications; and which client fields are required.' },
  { topic: 'Settings', q: 'How do I change the login page and logo?', a: 'In Settings → Login Page the Super Admin edits the headline, subtitle, stats and testimonial on the sign-in screen. The agency logo is set from the company branding and shows in the app and on the login page.' },

  // ---------------------------------------------------------------- My profile & shortcuts
  { topic: 'My profile & shortcuts', q: 'How do I update my profile and password?', a: 'Open My Profile to change your photo (camera icon, crop and save), personal details, and your password (current and new password). Your upcoming shifts are under “My schedule”.' },
  { topic: 'My profile & shortcuts', q: 'How do keyboard shortcuts work?', a: 'Open the shortcuts panel, click “+ Add shortcut”, press the key combination and choose the page it opens. If two shortcuts use the same keys, only the first runs.' },

  // ---------------------------------------------------------------- Help & support
  { topic: 'Help & support', q: 'How do I contact support?', a: 'Open Support, describe the problem and send — it is emailed to the support team. The About page describes the software and its provider.' },
  { topic: 'Help & support', q: 'How do Help Center videos work?', a: 'How-to videos appear under each topic of the Help Center for the roles they are shown to. Super Admins (and Admins or Managers when allowed) upload them with “Upload video”: choose the file, title, topic and who can watch. Videos are stored in the agency’s Cloudinary account.' },
];
